gal6(){return"\u062c\u0627\u0631\u064a \u0625\u0646\u0634\u0627\u0621 \u0627\u0644\u0625\u0637\u0627\u0631 \u0627\u0644\u0623\u0633\u0627\u0633\u064a \u0644\u0644\u0628\u0637\u0627\u0642\u0629..."},
ala(a,b,c){return"\u062c\u0627\u0631\u064a \u0631\u0633\u0645 \u0648\u062a\u062c\u0647\u064a\u0632 \u0627\u0644\u0633\u0637\u0631 ("+a+" \u0645\u0646 "+b+") \u0644\u0644\u0622\u064a\u0629 ("+c+")..."},
alb(a){return"\u062c\u0627\u0631\u064a \u0631\u0633\u0645 \u0648\u062a\u062c\u0647\u064a\u0632 \u0627\u0644\u0622\u064a\u0629 ("+a+")..."},
ale(a){return"\u062c\u0627\u0631\u064a \u0631\u0641\u0639 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u0642\u0637\u0639 ("+a+"%)..."},
galc(){return"\u062c\u0627\u0631\u064a \u0645\u0639\u0627\u0644\u062c\u0629 \u0648\u0625\u0646\u062a\u0627\u062c \u0645\u0642\u0637\u0639 \u0627\u0644\u0641\u064a\u062f\u064a\u0648..."},
gal8(){return"\u062c\u0627\u0631\u064a \u062a\u062d\u0636\u064a\u0631 \u0645\u0644\u0641 \u0627\u0644\u0641\u064a\u062f\u064a\u0648 \u0644\u0644\u062a\u062d\u0645\u064a\u0644..."},
gal5(){return"\u062c\u0627\u0631\u064a \u062a\u062c\u0645\u064a\u0639 \u0648\u062d\u0641\u0638 \u0627\u0644\u0641\u064a\u062f\u064a\u0648 \u0627\u0644\u0646\u0647\u0627\u0626\u064a..."},
a0L(a,b){return"\u062c\u0627\u0631\u064a \u0625\u0639\u062f\u0627\u062f \u0645\u0634\u0627\u0647\u062f \u0627\u0644\u0622\u064a\u0629 ("+a+" \u0645\u0646 "+b+")..."},
akO(a,b){return a+" / "+b},
akR(a){return"\u0645\u062a\u0628\u0642\u064a "+a+" \u062b\u0648\u0627\u0646\u064d \u062a\u0642\u0631\u064a\u0628\u064b\u0627 \u0644\u0625\u0646\u0647\u0627\u0621 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629"},
akS(a){return"\u0645\u062a\u0628\u0642\u064a "+a+" \u062b\u0627\u0646\u064a\u0629 \u062a\u0642\u0631\u064a\u0628\u064b\u0627 \u0644\u0625\u0646\u0647\u0627\u0621 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629"},
gakU(){return"\u0645\u062a\u0628\u0642\u064a \u062b\u0627\u0646\u064a\u0629 \u0648\u0627\u062d\u062f\u0629 \u062a\u0642\u0631\u064a\u0628\u064b\u0627 \u0644\u0625\u0646\u0647\u0627\u0621 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629"},
gakV(){return"\u0645\u062a\u0628\u0642\u064a \u062b\u0627\u0646\u064a\u062a\u0627\u0646 \u062a\u0642\u0631\u064a\u0628\u064b\u0627 \u0644\u0625\u0646\u0647\u0627\u0621 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629"},
gakT(){return"\u0645\u062a\u0628\u0642\u064a \u0644\u062d\u0638\u0627\u062a \u0644\u0625\u0646\u0647\u0627\u0621 \u0627\u0644\u0645\u0639\u0627\u0644\u062c\u0629..."},
gakG(){return"\u0641\u0634\u0644 \u0641\u064a \u0642\u064a\u0627\u0633 \u0645\u062f\u0629 \u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u0635\u0648\u062a\u064a \u0644\u0644\u062a\u0644\u0627\u0648\u0629"},
gal3(){return"\u062a\u0639\u0630\u0631 \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0628\u0627\u0644\u062e\u0627\u062f\u0645 \u0644\u062c\u0644\u0628 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062a\u0644\u0627\u0648\u0629. \u064a\u064f\u0631\u062c\u0649 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u062a\u0635\u0627\u0644\u0643 \u0628\u0627\u0644\u0625\u0646\u062a\u0631\u0646\u062a \u0648\u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629 \u0645\u062c\u062f\u062f\u064b\u0627."},
galf(){return"\u0644\u0627 \u062a\u062a\u0648\u0641\u0631 \u062a\u0633\u062c\u064a\u0644\u0627\u062a \u062a\u0648\u0642\u064a\u062a \u062f\u0642\u064a\u0642\u0629 \u0628\u0627\u0644\u0643\u0644\u0645\u0629 \u0644\u0647\u0630\u0627 \u0627\u0644\u0642\u0627\u0631\u0626 \u062d\u0627\u0644\u064a\u064b\u0627."},
galk(){return"\u062a\u0639\u0630\u0631 \u062c\u0644\u0628 \u0627\u0644\u062a\u0648\u0642\u064a\u062a \u0627\u0644\u062d\u0642\u064a\u0642\u064a \u0627\u0644\u062f\u0642\u064a\u0642 \u0644\u0643\u0644\u0645\u0627\u062a \u0627\u0644\u0622\u064a\u0629 \u0645\u0646 \u0627\u0644\u062e\u0627\u062f\u0645. \u064a\u064f\u0631\u062c\u0649 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u062a\u0635\u0627\u0644 \u0627\u0644\u0625\u0646\u062a\u0631\u0646\u062a."},
gakF(){return"\u062a\u0639\u0630\u0631 \u062a\u0646\u0632\u064a\u0644 \u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u0635\u0648\u062a\u064a \u0644\u0644\u062a\u0644\u0627\u0648\u0629. \u064a\u064f\u0631\u062c\u0649 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u062a\u0635\u0627\u0644\u0643 \u0628\u0627\u0644\u0625\u0646\u062a\u0631\u0646\u062a \u0648\u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629 \u0645\u062c\u062f\u062f\u064b\u0627."},
gakE(){return"\u062a\u0645 \u0625\u0644\u063a\u0627\u0621 \u062a\u062c\u0647\u064a\u0632 \u0627\u0644\u0645\u0644\u0641\u0627\u062a \u0627\u0644\u0635\u0648\u062a\u064a\u0629."},
galh(){return"\u062d\u062f\u062b \u062e\u0637\u0623 \u0623\u062b\u0646\u0627\u0621 \u0645\u0639\u0627\u0644\u062c\u0629 \u0648\u062a\u0631\u0645\u064a\u0632 \u0627\u0644\u0641\u064a\u062f\u064a\u0648. \u064a\u064f\u0631\u062c\u0649 \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649."},
galm(){return"\u062a\u0639\u0630\u0631 \u062a\u0635\u062f\u064a\u0631 \u0627\u0644\u0641\u064a\u062f\u064a\u0648 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0645\u062a\u0635\u0641\u062d. \u064a\u064f\u0631\u062c\u0649 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0645\u062a\u0635\u0641\u062d \u062d\u062f\u064a\u062b \u0645\u062b\u0644 Google Chrome."},
gakZ(){return"\u062d\u062c\u0645 \u0645\u0644\u0641 \u0627\u0644\u0641\u064a\u062f\u064a\u0648 \u0627\u0644\u0645\u062e\u0635\u0635 \u0643\u0628\u064a\u0631 \u062c\u062f\u064b\u0627 (\u0627\u0644\u062d\u062f \u0627\u0644\u0623\u0642\u0635\u0649 \u0627\u0644\u0645\u0633\u0645\u0648\u062d \u0628\u0647 150 \u0645\u064a\u062c\u0627\u0628\u0627\u064a\u062a). \u064a\u064f\u0631\u062c\u0649 \u0627\u062e\u062a\u064a\u0627\u0631 \u0645\u0642\u0637\u0639 \u0641\u064a\u062f\u064a\u0648 \u0623\u0635\u063a\u0631."},
gakX(){return"\u062a\u0639\u0630\u0631 \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0628\u062e\u0627\u062f\u0645 \u062a\u0635\u062f\u064a\u0631 \u0627\u0644\u0641\u064a\u062f\u064a\u0648 \u0639\u0644\u0649 \u0627\u0644\u0645\u0646\u0641\u0630 8080. \u064a\u064f\u0631\u062c\u0649 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u062a\u0634\u063a\u064a\u0644 \u0627\u0644\u0633\u064a\u0631\u0641\u0631 \u0648\u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629 \u0645\u062c\u062f\u062f\u064b\u0627."},
gal1(){return u.dd},
gakM(){return"\u0641\u0634\u0644 \u062a\u062d\u0645\u064a\u0644 \u0627\u0644\u0641\u064a\u062f\u064a\u0648 \u0645\u0646 \u0627\u0644\u0631\u0627\u0628\u0637 \u0627\u0644\u0645\u062d\u062f\u062f. \u064a\u064f\u0631\u062c\u0649 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u0644\u0631\u0627\u0628\u0637 \u0648\u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629 \u0645\u062c\u062f\u062f\u064b\u0627."},
gakN(){return"\u0645\u0644\u0641 \u0627\u0644\u0641\u064a\u062f\u064a\u0648 \u0627\u0644\u0645\u062e\u062a\u0627\u0631 \u0641\u0627\u0631\u063a \u0623\u0648 \u063a\u064a\u0631 \u0635\u0627\u0644\u062d. \u064a\u064f\u0631\u062c\u0649 \u0627\u062e\u062a\u064a\u0627\u0631 \u0645\u0642\u0637\u0639 \u0641\u064a\u062f\u064a\u0648 \u0622\u062e\u0631."},
